diff --git a/recreate/check.js b/recreate/check.js
new file mode 100644
index 000000000..9c1d0d0be
--- /dev/null
+++ b/recreate/check.js
@@ -0,0 +1,36 @@
+// Check for the report "Type assertion regression in TypeScript 5.7".
+// Expected: the type of `Test` in repro.ts is displayed as `{ prop1: "hello"; }`.
+// Exits non-zero while it is displayed as `{ prop1: Wrapper<"hello">; }`.
+//
+// Uses the freshly built compiler by default; set TS_LIB to the path of another
+// typescript.js (e.g. a published 5.6.3) to check that version instead.
+"use strict";
+const path = require("path");
+const ts = require(process.env.TS_LIB || path.join(__dirname, "..", "built", "local", "typescript.js"));
+
+const file = path.join(__dirname, "repro.ts");
+const program = ts.createProgram([file], {
+    strict: true,
+    target: ts.ScriptTarget.ES2022,
+    types: [],
+    noEmit: true,
+});
+const checker = program.getTypeChecker();
+const sourceFile = program.getSourceFile(file);
+
+let actual;
+ts.forEachChild(sourceFile, node => {
+    if (ts.isTypeAliasDeclaration(node) && node.name.text === "Test") {
+        actual = checker.typeToString(checker.getTypeAtLocation(node.name), /*enclosingDeclaration*/ undefined, ts.TypeFormatFlags.NoTruncation);
+    }
+});
+
+const expected = `{ prop1: "hello"; }`;
+console.log(`TypeScript ${ts.version}`);
+console.log(`expected: Test = ${expected}`);
+console.log(`actual:   Test = ${actual}`);
+if (actual !== expected) {
+    console.error("FAIL: Test is not displayed as expected");
+    process.exit(1);
+}
+console.log("PASS");
diff --git a/recreate/repro.ts b/recreate/repro.ts
new file mode 100644
index 000000000..7c28a519a
--- /dev/null
+++ b/recreate/repro.ts
@@ -0,0 +1,21 @@
+type Wrapper<T> = {
+    _type: T
+}
+
+function stringWrapper(): Wrapper<string> {
+    return { _type: "" }
+}
+
+function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> {
+    return { _type: obj }
+}
+
+const value = objWrapper({
+    prop1: stringWrapper() as Wrapper<"hello">
+})
+
+type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>> 
+    ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> } 
+    : T['_type']
+
+type Test = Unwrap<typeof value>
